+
+const PIXELFORMATDESCRIPTOR = extern struct {
+    nSize: u16,
+    nVersion: u16,
+    dwFlags: u32,
+    iPixelType: u8,
+    cColorBits: u8,
+    cRedBits: u8,
+    cRedShift: u8,
+    cGreenBits: u8,
+    cGreenShift: u8,
+    cBlueBits: u8,
+    cBlueShift: u8,
+    cAlphaBits: u8,
+    cAlphaShift: u8,
+    cAccumBits: u8,
+    cAccumRedBits: u8,
+    cAccumGreenBits: u8,
+    cAccumBlueBits: u8,
+    cAccumAlphaBits: u8,
+    cDepthBits: u8,
+    cStencilBits: u8,
+    cAuxBuffers: u8,
+    iLayerType: u8,
+    bReserved: u8,
+    dwLayerMask: u32,
+    dwVisibleMask: u32,
+    dwDamageMask: u32,
+};
+
+// WGL / GDI constants
+const PFD_DRAW_TO_WINDOW = 0x00000004;
+const PFD_SUPPORT_OPENGL = 0x00000020;
+const PFD_DOUBLEBUFFER = 0x00000001;
+const PFD_TYPE_RGBA = 0;
+const PFD_MAIN_PLANE = 0;
