+const RECT = extern struct { left: i32, top: i32, right: i32, bottom: i32 };
+extern "user32" fn GetClientRect(hWnd: HWND, lpRect: *RECT) callconv(.winapi) BOOL;
+
+pub fn swapBuffers(self: *Self) void {
+    if (self.hdc != null) {
+        _ = SwapBuffers(self.hdc);
