+/// Disable VSync via WGL extension for lower input latency.
+pub fn disableVSync(_: *Self) void {
+    const func: ?*const fn (i32) callconv(.winapi) i32 = @ptrCast(wglGetProcAddress("wglSwapIntervalEXT"));
