+pub fn getContentScale(self: *const Self) !apprt.ContentScale {
+    const dpi = GetDpiForWindow(self.hwnd);
+    if (dpi == 0) return .{ .x = 1.0, .y = 1.0 };
+    const scale: f32 = @as(f32, @floatFromInt(dpi)) / 96.0;
+    return .{ .x = scale, .y = scale };
